// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig, spring, interpolate, Img } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadRobotoMono = makeLoadFont('RobotoMono');

const { fontFamily: robotoMonoFamily } = loadRobotoMono();



export type SlideTimelineTransitionProps = Record<string, any>;

const SlideTimelineTransition: React.FC<SlideTimelineTransitionProps> = ({
  imageOne = "https://images.unsplash.com/photo-1444464666168-49d633b86797?q=80&w=1920&auto=format&fit=crop",
  imageTwo = "https://images.unsplash.com/photo-1506748686214-e9df14d4d9d0?q=80&w=1920&auto=format&fit=crop",
  textOne = "Malloy Studio",
  textTwo = "Creative Agency",
  textColor = "#ffffff",
  backgroundColor = "#111111",
  transparentBackground = false,
  durationInSeconds = 6,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Timings
  const slideStartFrame = fps * 1.5; // Transition starts at 1.5 seconds
  
  const textOneAppearFrame = fps * 0.5; // Starts at 0.5 seconds
  const textOneDisappearFrame = slideStartFrame - (fps * 0.3); // Disappears just before transition
  
  const textTwoAppearFrame = slideStartFrame + (fps * 0.8); // Appears after transition settles
  const textTwoDisappearFrame = (durationInSeconds * fps) - (fps * 0.5); // Disappears near the end
  
  // Transition driver - using an over-damped spring for a smooth, fast sweep that doesn't bounce
  const slideProgress = spring({
    frame: frame - slideStartFrame,
    fps,
    config: {
      damping: 20,
      stiffness: 40,
      mass: 1,
    },
  });

  // Slide images to the right through multiple phantom frames (x goes from 0 to +5 * width)
  const totalShifts = 5;
  const xOffset = interpolate(slideProgress, [0, 1], [0, totalShifts * width]);

  // Heavy Motion Blur effect along X-axis to blend the phantom slides
  const blurAmount = interpolate(
    slideProgress,
    [0, 0.1, 0.9, 1],
    [0, 120, 120, 0], // Massive blur during the middle 80% of the transition
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Slight horizontal scale to prevent edges from bleeding background color during heavy blur
  const scaleX = interpolate(blurAmount, [0, 120], [1, 1.15], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const isBlurring = blurAmount > 0.1;
  const filterStyle = isBlurring ? "url(#motion-blur)" : "none";

  // Text Box Scale Animations
  const textOneScaleIn = spring({
    frame: frame - textOneAppearFrame,
    fps,
    config: { damping: 12, stiffness: 100 },
  });

  const textOneScaleOut = spring({
    frame: frame - textOneDisappearFrame,
    fps,
    config: { damping: 12, stiffness: 100 },
  });

  const textOneScale = Math.max(0, textOneScaleIn - textOneScaleOut);

  const textTwoScaleIn = spring({
    frame: frame - textTwoAppearFrame,
    fps,
    config: { damping: 12, stiffness: 100 },
  });

  const textTwoScaleOut = spring({
    frame: frame - textTwoDisappearFrame,
    fps,
    config: { damping: 12, stiffness: 100 },
  });

  const textTwoScale = Math.max(0, textTwoScaleIn - textTwoScaleOut);

  // Define the sequence of slides including the blurred phantoms in between
  const slidesSequence = [
    { pos: 0, src: imageOne, overlayOpacity: 0 }, // Initial Image
    { pos: -1, src: imageTwo, overlayOpacity: 0.2 }, // Phantom 1
    { pos: -2, src: imageOne, overlayOpacity: 0.3 }, // Phantom 2
    { pos: -3, src: imageTwo, overlayOpacity: 0.4 }, // Phantom 3
    { pos: -4, src: imageOne, overlayOpacity: 0.2 }, // Phantom 4
    { pos: -5, src: imageTwo, overlayOpacity: 0 }, // Final Image
  ];

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      
      {/* SVG Filter for directional motion blur */}
      <svg width="0" height="0" style={{ position: "absolute" }}>
        <defs>
          <filter id="motion-blur" x="-50%" y="-50%" width="200%" height="200%">
            <feGaussianBlur in="SourceGraphic" stdDeviation={`${blurAmount} 0`} />
          </filter>
        </defs>
      </svg>

      {/* Container for sliding images */}
      <AbsoluteFill
        style={{
          transform: `translateX(${xOffset}px) scaleX(${scaleX})`,
          filter: filterStyle,
        }}
      >
        {slidesSequence.map((slide) => (
          <AbsoluteFill 
            key={slide.pos} 
            style={{ 
              position: "absolute", 
              left: slide.pos * width, 
              top: 0, 
              width, 
              height 
            }}
          >
            <Img
              src={slide.src}
              style={{
                width: "100%",
                height: "100%",
                objectFit: "cover",
              }}
            />
            {slide.overlayOpacity > 0 && (
              <AbsoluteFill 
                style={{ 
                  backgroundColor: `rgba(0, 0, 0, ${slide.overlayOpacity})` 
                }} 
              />
            )}
          </AbsoluteFill>
        ))}
      </AbsoluteFill>

      {/* Text Box One overlay */}
      <AbsoluteFill
        style={{
          justifyContent: "flex-end",
          alignItems: "center",
          paddingBottom: height * 0.15,
          pointerEvents: "none",
        }}
      >
        <div
          style={{
            transform: `scale(${textOneScale})`,
            opacity: textOneScale,
            display: "flex",
            alignItems: "center",
            backgroundColor: "rgba(0, 0, 0, 0.4)",
            padding: "20px 60px",
            borderRadius: "100px",
            backdropFilter: "blur(12px)",
            border: "1px solid rgba(255, 255, 255, 0.15)",
            boxShadow: "0 20px 40px rgba(0, 0, 0, 0.5)",
          }}
        >
          <span
            style={{
              fontFamily: robotoMonoFamily,
              fontSize: "60px",
              fontWeight: 700,
              color: textColor,
              lineHeight: 1,
            }}
          >
            {textOne}
          </span>
        </div>
      </AbsoluteFill>

      {/* Text Box Two overlay */}
      <AbsoluteFill
        style={{
          justifyContent: "flex-end",
          alignItems: "center",
          paddingBottom: height * 0.15,
          pointerEvents: "none",
        }}
      >
        <div
          style={{
            transform: `scale(${textTwoScale})`,
            opacity: textTwoScale,
            display: "flex",
            alignItems: "center",
            backgroundColor: "rgba(0, 0, 0, 0.4)",
            padding: "20px 60px",
            borderRadius: "100px",
            backdropFilter: "blur(12px)",
            border: "1px solid rgba(255, 255, 255, 0.15)",
            boxShadow: "0 20px 40px rgba(0, 0, 0, 0.5)",
          }}
        >
          <span
            style={{
              fontFamily: robotoMonoFamily,
              fontSize: "60px",
              fontWeight: 700,
              color: textColor,
              lineHeight: 1,
            }}
          >
            {textTwo}
          </span>
        </div>
      </AbsoluteFill>
      
    </AbsoluteFill>
  );
};

export default SlideTimelineTransition;